insert into public.recipes (id, title, description, emoji, color, image_url, cuisine, tags, meal_types, servings, prep_time_min, cook_time_min, difficulty, equipment, steps, kcal_per_serving, cost_level, is_published) values
  ('rec_curry_pois_chiches', 'Curry de pois chiches au lait de coco', 'Un curry doux et crémeux, prêt en une demi-heure, qui réchauffe sans piquer.', '🍛', '#F9E3B8', null, 'indienne'::public.cuisine, array['familial', 'batch', 'végétal']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 20, 1, array['plaques']::public.equipment[], '[{"text":"Lance la cuisson du riz basmati dans une grande casserole d''eau bouillante salée.","timerMin":11},{"text":"Émince l''oignon, hache l''ail et râpe le gingembre."},{"text":"Fais revenir l''oignon dans l''huile à feu moyen, puis ajoute l''ail, le gingembre et le curry pendant 1 minute.","timerMin":4},{"text":"Verse les tomates concassées, les pois chiches égouttés et le lait de coco. Laisse mijoter à petits bouillons.","timerMin":15},{"text":"Incorpore les pousses d''épinards hors du feu : elles tombent en une minute."},{"text":"Sale, parsème de coriandre ciselée et sers bien chaud avec le riz."}]'::jsonb, 560, 1, true),
  ('rec_dahl_lentilles_corail', 'Dahl de lentilles corail', 'Des lentilles fondantes parfumées au cumin et au curcuma, relevées d’un trait de citron vert.', '🥣', '#FAD7B5', null, 'indienne'::public.cuisine, array['familial', 'batch', 'végétal', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 25, 1, array['plaques']::public.equipment[], '[{"text":"Rince les lentilles corail à l''eau froide jusqu''à ce que l''eau soit claire."},{"text":"Émince l''oignon et fais-le dorer dans l''huile avec l''ail haché et le gingembre râpé.","timerMin":4},{"text":"Ajoute le cumin et le curcuma, mélange 30 secondes pour réveiller les épices."},{"text":"Verse les lentilles, les tomates, le lait de coco et l''eau. Laisse cuire à feu doux en remuant de temps en temps.","timerMin":20},{"text":"Pendant ce temps, fais cuire le riz basmati.","timerMin":11},{"text":"Arrose de jus de citron vert, rectifie le sel et sers avec le riz et la coriandre."}]'::jsonb, 520, 1, true),
  ('rec_chili_sin_carne', 'Chili sin carne', 'Haricots rouges, maïs et poivron mijotés aux épices mexicaines : généreux et 100 % végétal.', '🌶️', '#F6C9B8', null, 'mexicaine'::public.cuisine, array['batch', 'végétal', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 25, 1, array['plaques']::public.equipment[], '[{"text":"Émince l''oignon, coupe le poivron en dés et hache l''ail."},{"text":"Fais revenir l''oignon et le poivron dans l''huile d''olive.","timerMin":5},{"text":"Ajoute l''ail, le cumin, le paprika et le piment, mélange 1 minute."},{"text":"Verse les tomates, les haricots rouges et le maïs égouttés. Laisse mijoter à couvert.","timerMin":20},{"text":"Fais cuire le riz pendant que le chili mijote.","timerMin":11},{"text":"Goûte, sale, et sers le chili sur le riz."}]'::jsonb, 540, 1, true),
  ('rec_ratatouille', 'Ratatouille provençale', 'Le grand classique de l’été : des légumes du soleil confits doucement à l’huile d’olive.', '🍆', '#E5D4EF', null, 'francaise'::public.cuisine, array['de saison', 'batch', 'végétal', 'léger']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 45, 2, array['plaques']::public.equipment[], '[{"text":"Coupe tous les légumes en dés de taille égale (environ 2 cm)."},{"text":"Fais revenir l''aubergine dans 2 cuillères d''huile jusqu''à ce qu''elle dore, puis réserve-la.","timerMin":8},{"text":"Dans la même cocotte, fais suer l''oignon et les poivrons avec le reste d''huile.","timerMin":7},{"text":"Ajoute les courgettes, l''ail écrasé, les tomates et les herbes de Provence.","timerMin":2},{"text":"Remets l''aubergine, sale, poivre, couvre et laisse confire à feu doux en remuant de temps en temps.","timerMin":30},{"text":"Sers chaud, tiède ou froid : elle est encore meilleure le lendemain."}]'::jsonb, 210, 2, true),
  ('rec_buddha_bowl_patate_douce', 'Buddha bowl patate douce & pois chiches', 'Quinoa, patate douce rôtie, avocat et sauce tahini citronnée : un bol complet et coloré.', '🥗', '#FBE0C8', null, 'monde'::public.cuisine, array['léger', 'végétal', 'de saison']::text[], array['dejeuner']::public.meal_type[], 4, 15, 25, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 210 °C."},{"text":"Coupe la patate douce en cubes, mélange-les avec les pois chiches, le cumin, 2 cuillères d''huile et le sel, puis enfourne.","timerMin":25},{"text":"Rince le quinoa et fais-le cuire dans deux fois son volume d''eau salée.","timerMin":12},{"text":"Fouette le tahini avec le jus du citron, 1 cuillère d''huile et un peu d''eau pour obtenir une sauce nappante."},{"text":"Coupe les avocats en tranches."},{"text":"Compose les bols : quinoa, pousses d’épinards, légumes rôtis, avocat, puis nappe de sauce."}]'::jsonb, 590, 2, true),
  ('rec_veloute_butternut_coco', 'Velouté de butternut au lait de coco', 'Une soupe veloutée et légèrement sucrée, relevée d’une pointe de muscade.', '🎃', '#FCD9A8', null, 'francaise'::public.cuisine, array['de saison', 'léger', 'végétal', 'batch']::text[], array['diner']::public.meal_type[], 4, 15, 25, 1, array['plaques', 'mixeur']::public.equipment[], '[{"text":"Épluche la butternut, retire les graines et coupe la chair en cubes."},{"text":"Fais revenir l''oignon émincé dans l''huile.","timerMin":3},{"text":"Ajoute la courge, le cube de bouillon émietté et l''eau. Laisse cuire jusqu''à ce que la courge soit tendre.","timerMin":20},{"text":"Mixe finement en ajoutant le lait de coco."},{"text":"Assaisonne de muscade et de sel, puis sers bien chaud."}]'::jsonb, 230, 1, true),
  ('rec_tofu_nouilles_legumes', 'Nouilles sautées au tofu et brocoli', 'Un wok express où le tofu croustillant rencontre des légumes croquants et une sauce soja-gingembre.', '🍜', '#DDEBC8', null, 'asiatique'::public.cuisine, array['rapide', 'végétal']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 10, 2, array['plaques']::public.equipment[], '[{"text":"Fais tremper les nouilles de riz dans l''eau bouillante hors du feu, puis égoutte-les.","timerMin":5},{"text":"Coupe le tofu en cubes, le brocoli en petits bouquets et les carottes en julienne."},{"text":"Fais dorer le tofu dans l''huile de tournesol bien chaude, puis réserve-le.","timerMin":5},{"text":"Saute les légumes avec l''ail et le gingembre en gardant du croquant.","timerMin":4},{"text":"Ajoute les nouilles, le tofu, la sauce soja et l’huile de sésame, mélange 1 minute.","timerMin":1},{"text":"Parsème d’oignon nouveau ciselé et de graines de sésame."}]'::jsonb, 530, 2, true),
  ('rec_taboule_libanais', 'Taboulé libanais', 'Beaucoup d’herbes, un peu de boulgour, du citron : la version fraîche et vraie du taboulé.', '🌿', '#D6EBC4', null, 'orientale'::public.cuisine, array['léger', 'végétal', 'de saison']::text[], array['dejeuner']::public.meal_type[], 4, 25, 0, 1, '{}'::public.equipment[], '[{"text":"Couvre le boulgour d''eau chaude salée et laisse-le gonfler.","timerMin":15},{"text":"Pendant ce temps, cisèle finement le persil et la menthe."},{"text":"Coupe les tomates, le concombre et l''oignon rouge en tout petits dés."},{"text":"Égoutte le boulgour en le pressant bien."},{"text":"Mélange tout avec le jus des citrons et l''huile d''olive, sale et garde au frais jusqu''au service."}]'::jsonb, 290, 1, true),
  ('rec_spaghetti_tomate_basilic', 'Spaghetti à la tomate et au basilic', 'La sauce tomate maison en 15 minutes, parfumée à l’ail et au basilic frais.', '🍝', '#F8CFC4', null, 'italienne'::public.cuisine, array['rapide', 'familial', 'végétal']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 5, 12, 1, array['plaques']::public.equipment[], '[{"text":"Fais cuire les spaghetti dans une grande casserole d''eau bouillante salée.","timerMin":10},{"text":"Fais revenir l''ail émincé dans l''huile d''olive sans le laisser colorer.","timerMin":1},{"text":"Ajoute le coulis, le sucre et une pincée de sel, laisse frémir.","timerMin":10},{"text":"Égoutte les pâtes en gardant un fond d’eau de cuisson et mélange-les à la sauce."},{"text":"Ajoute le basilic ciselé au dernier moment."}]'::jsonb, 480, 1, true),
  ('rec_falafels_maison', 'Falafels maison, sauce tahini', 'Des boulettes de pois chiches aux herbes, dorées à la poêle et glissées dans un pain pita.', '🧆', '#E8DDB5', null, 'orientale'::public.cuisine, array['végétal', 'street food']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 25, 15, 3, array['mixeur', 'plaques']::public.equipment[], '[{"text":"Égoutte et sèche soigneusement les pois chiches."},{"text":"Mixe-les avec l''oignon, l''ail, les herbes, le cumin, la farine et le sel jusqu''à obtenir une pâte granuleuse."},{"text":"Forme des boulettes légèrement aplaties (environ 16)."},{"text":"Fais-les dorer dans l''huile chaude, en plusieurs fournées, 3 minutes par face.","timerMin":12},{"text":"Mélange le tahini, le jus de citron et un peu d''eau pour faire la sauce."},{"text":"Garnis les pitas réchauffées de falafels, de tomate en dés et de sauce."}]'::jsonb, 610, 1, true),
  ('rec_lentilles_carottes', 'Lentilles vertes mijotées aux carottes', 'Un plat de bistrot réconfortant, relevé d’une cuillère de moutarde à l’ancienne.', '🫘', '#E6DCC6', null, 'francaise'::public.cuisine, array['batch', 'végétal', 'comfort', 'de saison']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 30, 1, array['plaques']::public.equipment[], '[{"text":"Coupe les carottes en rondelles et émince l''oignon."},{"text":"Fais-les revenir dans l''huile d''olive avec l''ail.","timerMin":4},{"text":"Ajoute les lentilles rincées, l''eau, le cube de bouillon, le laurier et le thym.","timerMin":1},{"text":"Laisse mijoter à couvert jusqu''à ce que les lentilles soient tendres.","timerMin":25},{"text":"Hors du feu, incorpore la moutarde et parsème de persil haché."}]'::jsonb, 380, 1, true),
  ('rec_couscous_legumes', 'Couscous aux légumes et pois chiches', 'Un bouillon parfumé au ras el hanout, des légumes fondants et une semoule bien aérée.', '🥘', '#F7DDB0', null, 'orientale'::public.cuisine, array['familial', 'végétal', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 35, 2, array['plaques']::public.equipment[], '[{"text":"Fais revenir l''oignon émincé dans 2 cuillères d''huile avec le ras el hanout.","timerMin":3},{"text":"Ajoute les carottes en tronçons, les tomates, le cube de bouillon et l''eau. Laisse cuire.","timerMin":15},{"text":"Ajoute les courgettes en morceaux et les pois chiches, poursuis la cuisson.","timerMin":15},{"text":"Verse la semoule dans un saladier avec 1 cuillère d''huile, couvre-la du même volume d''eau bouillante salée.","timerMin":5},{"text":"Égrène la semoule à la fourchette."},{"text":"Sers la semoule arrosée de bouillon et garnie de légumes."}]'::jsonb, 560, 1, true),
  ('rec_minestrone', 'Minestrone aux haricots rouges', 'Une soupe-repas italienne pleine de légumes, de petites pâtes et de haricots.', '🥕', '#F3D9C2', null, 'italienne'::public.cuisine, array['batch', 'végétal', 'anti-gaspi', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 30, 1, array['plaques']::public.equipment[], '[{"text":"Coupe la carotte, la courgette, le céleri et l’oignon en petits dés."},{"text":"Fais-les suer dans l''huile d''olive avec l''ail.","timerMin":5},{"text":"Ajoute les tomates, l''eau et le cube de bouillon. Laisse mijoter.","timerMin":15},{"text":"Ajoute les coquillettes et les haricots rouges égouttés.","timerMin":10},{"text":"Sers avec du basilic ciselé."}]'::jsonb, 360, 1, true),
  ('rec_risotto_champignons', 'Risotto crémeux aux champignons', 'Un risotto onctueux au parmesan, avec des champignons dorés au beurre.', '🍄', '#EADFCF', null, 'italienne'::public.cuisine, array['comfort', 'de saison']::text[], array['diner']::public.meal_type[], 4, 10, 25, 2, array['plaques']::public.equipment[], '[{"text":"Dissous les cubes de bouillon dans l''eau chaude et garde-la frémissante."},{"text":"Fais dorer les champignons émincés dans la moitié du beurre, puis réserve-les.","timerMin":6},{"text":"Fais suer l''oignon haché dans l''huile, ajoute le riz et nacre-le jusqu''à ce qu''il soit translucide.","timerMin":2},{"text":"Déglace au vin blanc, puis ajoute le bouillon louche par louche en remuant, à mesure qu''il est absorbé.","timerMin":18},{"text":"Hors du feu, incorpore les champignons, le reste du beurre et le parmesan râpé."},{"text":"Laisse reposer 2 minutes à couvert et sers avec du persil."}]'::jsonb, 540, 2, true),
  ('rec_tortilla_espagnole', 'Tortilla espagnole aux pommes de terre', 'Une omelette épaisse et moelleuse aux pommes de terre fondantes et à l’oignon.', '🥔', '#FBEBB5', null, 'mediterraneenne'::public.cuisine, array['familial', 'anti-gaspi']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 25, 2, array['plaques']::public.equipment[], '[{"text":"Épluche les pommes de terre et coupe-les en fines lamelles, émince l''oignon."},{"text":"Fais-les cuire doucement dans l''huile d''olive, sans coloration, jusqu''à ce qu''elles soient tendres.","timerMin":15},{"text":"Bats les œufs avec le sel et le poivre, ajoute les pommes de terre égouttées."},{"text":"Verse dans la poêle et laisse prendre à feu doux.","timerMin":6},{"text":"Retourne la tortilla à l''aide d''une assiette et poursuis la cuisson.","timerMin":4},{"text":"Sers tiède avec une salade verte."}]'::jsonb, 390, 1, true),
  ('rec_quiche_poireaux_chevre', 'Quiche poireaux et chèvre', 'Des poireaux fondus et du chèvre crémeux sur une pâte brisée bien croustillante.', '🥧', '#E4EDCB', null, 'francaise'::public.cuisine, array['de saison', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 20, 35, 2, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 190 °C et étale la pâte dans un moule."},{"text":"Émince les poireaux et fais-les fondre dans le beurre à feu doux.","timerMin":10},{"text":"Bats les œufs avec la crème, le lait, la muscade et le sel."},{"text":"Répartis les poireaux sur la pâte, ajoute le chèvre en rondelles et verse l’appareil."},{"text":"Enfourne jusqu’à ce que la quiche soit dorée et prise.","timerMin":35}]'::jsonb, 450, 2, true),
  ('rec_lasagnes_epinards_ricotta', 'Lasagnes épinards-ricotta', 'Des couches fondantes d’épinards, de ricotta et de mozzarella gratinée.', '🧀', '#DDEAC9', null, 'italienne'::public.cuisine, array['familial', 'batch', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 25, 40, 2, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 180 °C."},{"text":"Fais décongeler les épinards à la poêle avec l''ail et l''huile, puis égoutte-les bien.","timerMin":8},{"text":"Mélange les épinards avec la ricotta, la muscade et le sel."},{"text":"Monte les lasagnes : coulis, feuilles, mélange épinards-ricotta, et recommence en terminant par du coulis."},{"text":"Couvre de mozzarella en tranches et de parmesan râpé."},{"text":"Enfourne jusqu''à ce que le dessus soit bien gratiné.","timerMin":35}]'::jsonb, 520, 2, true),
  ('rec_shakshuka', 'Shakshuka', 'Des œufs pochés dans une sauce tomate-poivron épicée, à saucer sans modération.', '🍳', '#F7C6B2', null, 'orientale'::public.cuisine, array['rapide', 'léger']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 15, 1, array['plaques']::public.equipment[], '[{"text":"Fais revenir l''oignon et le poivron émincés dans l''huile.","timerMin":5},{"text":"Ajoute l''ail, le cumin et le paprika, puis les tomates. Laisse épaissir.","timerMin":5},{"text":"Creuse 6 puits dans la sauce et casse un œuf dans chacun."},{"text":"Couvre et laisse cuire jusqu’à ce que les blancs soient pris.","timerMin":5},{"text":"Parsème de coriandre et sers directement dans la poêle."}]'::jsonb, 260, 1, true),
  ('rec_gnocchis_pesto_tomates', 'Gnocchis poêlés, pesto et tomates cerises', 'Des gnocchis dorés et croustillants, enrobés de pesto avec des tomates cerises éclatées.', '🍅', '#D9ECC9', null, 'italienne'::public.cuisine, array['rapide', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 5, 10, 1, array['plaques']::public.equipment[], '[{"text":"Fais dorer les gnocchis dans l''huile d''olive à feu vif en les remuant souvent.","timerMin":7},{"text":"Ajoute les tomates cerises coupées en deux et laisse-les éclater.","timerMin":3},{"text":"Hors du feu, enrobe de pesto."},{"text":"Sers avec quelques copeaux de parmesan."}]'::jsonb, 520, 2, true),
  ('rec_salade_grecque', 'Salade grecque', 'Tomates juteuses, concombre, olives et feta, arrosés d’huile d’olive et d’origan.', '🫒', '#DCEFD9', null, 'mediterraneenne'::public.cuisine, array['rapide', 'léger', 'de saison', 'sans cuisson']::text[], array['dejeuner']::public.meal_type[], 4, 15, 0, 1, '{}'::public.equipment[], '[{"text":"Coupe les tomates en quartiers et le concombre en demi-rondelles."},{"text":"Émince finement l''oignon rouge."},{"text":"Réunis les légumes et les olives dans un saladier."},{"text":"Pose la feta en gros morceaux, arrose d''huile et de vinaigre, puis parsème d''origan."}]'::jsonb, 310, 2, true),
  ('rec_pizza_margherita', 'Pizza margherita maison', 'Une pâte fine, un coulis de tomate, de la mozzarella filante et du basilic frais.', '🍕', '#FAD3C8', null, 'italienne'::public.cuisine, array['familial', 'week-end']::text[], array['diner']::public.meal_type[], 2, 10, 15, 1, array['four']::public.equipment[], '[{"text":"Préchauffe le four à 240 °C avec la plaque à l’intérieur."},{"text":"Déroule la pâte sur du papier cuisson et étale le coulis en laissant 1 cm de bord."},{"text":"Ajoute la mozzarella égouttée et déchirée, l''origan et un filet d''huile."},{"text":"Fais glisser sur la plaque chaude et enfourne.","timerMin":13},{"text":"Parsème de basilic frais à la sortie du four."}]'::jsonb, 640, 1, true),
  ('rec_soupe_oignon', 'Soupe à l''oignon gratinée', 'Des oignons longuement caramélisés, un bouillon parfumé et un croûton gratiné.', '🧅', '#EBD6B8', null, 'francaise'::public.cuisine, array['comfort', 'de saison']::text[], array['diner']::public.meal_type[], 4, 15, 45, 2, array['plaques', 'four']::public.equipment[], '[{"text":"Émince finement les oignons."},{"text":"Fais-les caraméliser dans le beurre à feu doux en remuant régulièrement.","timerMin":25},{"text":"Saupoudre de farine, mélange, puis déglace au vin blanc.","timerMin":2},{"text":"Ajoute l''eau, les cubes de bouillon et le thym. Laisse mijoter.","timerMin":15},{"text":"Verse dans des bols allant au four, pose une tranche de pain et couvre de comté râpé."},{"text":"Fais gratiner sous le gril du four.","timerMin":5}]'::jsonb, 420, 1, true),
  ('rec_omelette_champignons', 'Omelette baveuse aux champignons', 'Une omelette moelleuse, des champignons dorés et une poignée de ciboulette.', '🥚', '#FCEFC0', null, 'francaise'::public.cuisine, array['rapide', 'léger']::text[], array['dejeuner', 'diner']::public.meal_type[], 2, 10, 10, 1, array['plaques']::public.equipment[], '[{"text":"Émince les champignons et fais-les dorer dans la moitié du beurre.","timerMin":5},{"text":"Bats les œufs avec le sel, le poivre et la ciboulette ciselée."},{"text":"Fais fondre le reste du beurre, verse les œufs et remue doucement jusqu’à ce qu’ils soient presque pris.","timerMin":3},{"text":"Ajoute les champignons, plie l’omelette et sers aussitôt avec la salade."}]'::jsonb, 330, 1, true),
  ('rec_quesadillas_haricots', 'Quesadillas haricots, maïs et fromage', 'Des tortillas croustillantes garnies de haricots épicés et de fromage fondant.', '🌮', '#FBE3B0', null, 'mexicaine'::public.cuisine, array['rapide', 'familial', 'street food']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 10, 1, array['plaques']::public.equipment[], '[{"text":"Écrase grossièrement les haricots avec le cumin."},{"text":"Coupe le poivron en petits dés."},{"text":"Garnis 4 tortillas de haricots, de maïs, de poivron et de fromage, puis couvre avec les 4 autres."},{"text":"Fais-les dorer à la poêle sans matière grasse, 2 minutes par face.","timerMin":8},{"text":"Coupe en parts et sers avec l''avocat en tranches."}]'::jsonb, 560, 1, true),
  ('rec_mac_and_cheese', 'Mac and cheese gratiné', 'Des coquillettes nappées d’une sauce au fromage crémeuse, gratinées au four.', '🧀', '#FDE7A9', null, 'americaine'::public.cuisine, array['comfort', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 25, 1, array['plaques', 'four']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C et fais cuire les coquillettes al dente.","timerMin":8},{"text":"Fais fondre le beurre, ajoute la farine et mélange 1 minute.","timerMin":1},{"text":"Verse le lait petit à petit en fouettant jusqu’à épaississement.","timerMin":5},{"text":"Ajoute le cheddar en morceaux, la moitié de l’emmental, la muscade et le sel."},{"text":"Mélange avec les pâtes, verse dans un plat et couvre du reste d’emmental."},{"text":"Fais gratiner au four.","timerMin":12}]'::jsonb, 640, 1, true),
  ('rec_gratin_chou_fleur', 'Gratin de chou-fleur', 'Du chou-fleur tendre sous une béchamel à la muscade et une croûte dorée d’emmental.', '🥦', '#EEF0D8', null, 'francaise'::public.cuisine, array['de saison', 'comfort', 'familial']::text[], array['diner']::public.meal_type[], 4, 15, 35, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C."},{"text":"Détaille le chou-fleur en bouquets et fais-les cuire à l''eau bouillante salée.","timerMin":10},{"text":"Prépare la béchamel : beurre fondu, farine, puis lait versé en fouettant.","timerMin":6},{"text":"Assaisonne de muscade et de sel."},{"text":"Dispose le chou-fleur égoutté dans un plat, nappe de béchamel et parsème d''emmental."},{"text":"Fais gratiner.","timerMin":20}]'::jsonb, 340, 1, true),
  ('rec_veloute_poireaux_pdt', 'Velouté poireaux-pommes de terre', 'La soupe de grand-mère, douce et veloutée, avec une touche de crème.', '🥬', '#E3EFD3', null, 'francaise'::public.cuisine, array['de saison', 'léger', 'anti-gaspi', 'batch']::text[], array['diner']::public.meal_type[], 4, 15, 25, 1, array['plaques', 'mixeur']::public.equipment[], '[{"text":"Lave et émince les poireaux, épluche et coupe les pommes de terre en cubes."},{"text":"Fais suer les poireaux et l''oignon dans le beurre.","timerMin":5},{"text":"Ajoute les pommes de terre, l''eau et le cube de bouillon. Laisse cuire.","timerMin":20},{"text":"Mixe en ajoutant la crème, sale et sers bien chaud."}]'::jsonb, 240, 1, true),
  ('rec_salade_chevre_chaud', 'Salade de chèvre chaud au miel et aux noix', 'Des toasts de chèvre fondant au miel sur une salade croquante aux noix.', '🥖', '#F1EBC9', null, 'francaise'::public.cuisine, array['rapide', 'léger']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 8, 1, array['four']::public.equipment[], '[{"text":"Préchauffe le four en position gril."},{"text":"Coupe la baguette en tranches et pose une rondelle de chèvre sur chacune."},{"text":"Arrose d’un filet de miel et fais gratiner.","timerMin":6},{"text":"Prépare la vinaigrette avec l''huile, le vinaigre balsamique et le sel."},{"text":"Assaisonne la salade, ajoute les noix concassées et dépose les toasts chauds."}]'::jsonb, 470, 2, true),
  ('rec_saumon_papillote', 'Saumon en papillote, courgettes et citron', 'Un saumon fondant cuit à l’étouffée sur un lit de courgettes, servi avec du riz.', '🐟', '#FAD4C6', null, 'francaise'::public.cuisine, array['rapide', 'léger']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 15, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C et lance la cuisson du riz.","timerMin":11},{"text":"Coupe les courgettes en fines rondelles et le citron en tranches."},{"text":"Sur 4 feuilles de papier cuisson, dispose les courgettes, un pavé de saumon, deux tranches de citron, un filet d''huile, sel et poivre."},{"text":"Ferme les papillotes et enfourne.","timerMin":15},{"text":"Ouvre à table et parsème de ciboulette ciselée."}]'::jsonb, 520, 3, true),
  ('rec_tagliatelles_saumon_fume', 'Tagliatelles au saumon fumé', 'Une sauce crème-citron toute simple qui enrobe des tagliatelles et du saumon fumé.', '🍝', '#FBDCD0', null, 'italienne'::public.cuisine, array['rapide', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 5, 15, 1, array['plaques']::public.equipment[], '[{"text":"Fais cuire les tagliatelles dans l''eau bouillante salée.","timerMin":8},{"text":"Coupe le saumon fumé en lanières."},{"text":"Fais chauffer la crème avec le zeste et le jus du demi-citron.","timerMin":3},{"text":"Mélange les pâtes égouttées avec la crème, puis ajoute le saumon hors du feu."},{"text":"Poivre et parsème de ciboulette."}]'::jsonb, 610, 3, true),
  ('rec_moules_marinieres', 'Moules marinières', 'Des moules ouvertes au vin blanc, à l’échalote et au persil, à partager en famille.', '🦪', '#D7E3F0', null, 'francaise'::public.cuisine, array['de saison', 'convivial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 10, 1, array['plaques']::public.equipment[], '[{"text":"Gratte et rince les moules ; jette celles qui restent ouvertes quand on les tapote."},{"text":"Fais suer les échalotes hachées dans le beurre dans un grand faitout.","timerMin":3},{"text":"Ajoute le vin blanc et les moules, couvre et secoue la cocotte de temps en temps.","timerMin":6},{"text":"Dès qu''elles sont ouvertes, parsème de persil haché et poivre."},{"text":"Sers aussitôt avec du pain pour saucer."}]'::jsonb, 420, 2, true),
  ('rec_curry_crevettes_coco', 'Curry de crevettes au lait de coco', 'Des crevettes juste saisies dans une sauce coco parfumée au curry et au gingembre.', '🍤', '#FCDDC2', null, 'asiatique'::public.cuisine, array['rapide', 'épicé']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 15, 1, array['plaques']::public.equipment[], '[{"text":"Lance la cuisson du riz.","timerMin":11},{"text":"Fais revenir l''oignon, l''ail et le gingembre dans l''huile.","timerMin":3},{"text":"Ajoute le curry, les tomates et le lait de coco, laisse réduire.","timerMin":8},{"text":"Plonge les crevettes et laisse-les chauffer sans bouillir.","timerMin":3},{"text":"Parsème de coriandre et sers avec le riz."}]'::jsonb, 540, 3, true),
  ('rec_cabillaud_puree', 'Cabillaud rôti et purée maison', 'Un dos de cabillaud nacré, une purée onctueuse au beurre et un trait de citron.', '🐠', '#E2ECF2', null, 'francaise'::public.cuisine, array['familial', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 25, 2, array['plaques', 'four']::public.equipment[], '[{"text":"Épluche les pommes de terre et fais-les cuire à l''eau salée.","timerMin":20},{"text":"Préchauffe le four à 200 °C."},{"text":"Dépose le cabillaud dans un plat, arrose d''huile et de jus de citron, sale, puis enfourne.","timerMin":12},{"text":"Écrase les pommes de terre avec le lait chaud, le beurre et la muscade."},{"text":"Sers le poisson sur la purée, parsemé de persil."}]'::jsonb, 470, 3, true),
  ('rec_salade_nicoise', 'Salade niçoise', 'Thon, œufs durs, haricots verts et olives : une assiette complète et ensoleillée.', '🥗', '#E2F0D0', null, 'francaise'::public.cuisine, array['léger', 'de saison']::text[], array['dejeuner']::public.meal_type[], 4, 20, 15, 1, array['plaques']::public.equipment[], '[{"text":"Fais cuire les pommes de terre à l''eau salée.","timerMin":15},{"text":"Fais durcir les œufs, puis refroidis-les sous l’eau froide.","timerMin":10},{"text":"Fais cuire les haricots verts pour qu’ils restent croquants.","timerMin":7},{"text":"Coupe tomates, pommes de terre et œufs en quartiers."},{"text":"Dresse sur la salade avec le thon, les olives et l’oignon émincé, puis arrose de vinaigrette."}]'::jsonb, 430, 2, true),
  ('rec_poke_bowl_saumon', 'Poke bowl au saumon', 'Riz tiède, saumon mariné soja-sésame, avocat et concombre croquant.', '🍣', '#FCD6CB', null, 'monde'::public.cuisine, array['léger', 'tendance']::text[], array['dejeuner']::public.meal_type[], 4, 20, 12, 2, array['plaques']::public.equipment[], '[{"text":"Fais cuire le riz et laisse-le tiédir.","timerMin":12},{"text":"Coupe le saumon en cubes et fais-le mariner avec la sauce soja, l’huile de sésame et le jus de citron vert.","timerMin":10},{"text":"Coupe l''avocat et le concombre en dés, cisèle l''oignon nouveau."},{"text":"Répartis le riz dans les bols et dispose joliment saumon, avocat et concombre."},{"text":"Parsème de sésame et d’oignon nouveau."}]'::jsonb, 590, 3, true),
  ('rec_tacos_poisson', 'Tacos de cabillaud, crème citron vert', 'Du poisson épicé, de l’avocat et une sauce yaourt-citron vert dans des tortillas tièdes.', '🌮', '#DFF0E4', null, 'mexicaine'::public.cuisine, array['rapide', 'street food']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 10, 1, array['plaques']::public.equipment[], '[{"text":"Frotte le poisson avec le paprika, le cumin et le sel."},{"text":"Fais-le cuire à la poêle dans l''huile, puis effeuille-le.","timerMin":8},{"text":"Mélange le yaourt avec le jus d’un citron vert."},{"text":"Réchauffe les tortillas à sec.","timerMin":2},{"text":"Garnis de poisson, d’avocat, de sauce et de coriandre ; sers avec des quartiers de citron vert."}]'::jsonb, 510, 3, true),
  ('rec_paella_crevettes_chorizo', 'Paella express crevettes-chorizo', 'Un riz safrané au paprika, généreux en crevettes, chorizo et petits pois.', '🥘', '#FCE0A8', null, 'mediterraneenne'::public.cuisine, array['convivial', 'week-end']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 30, 3, array['plaques']::public.equipment[], '[{"text":"Fais revenir le chorizo en rondelles dans une grande poêle, puis réserve-le.","timerMin":3},{"text":"Fais suer l''oignon, l''ail et le poivron dans la même poêle avec l''huile.","timerMin":5},{"text":"Ajoute le riz, le paprika et le curcuma, mélange pour bien enrober.","timerMin":2},{"text":"Verse l''eau chaude et le cube de bouillon, puis laisse cuire sans remuer.","timerMin":15},{"text":"Ajoute les petits pois, les crevettes et le chorizo, poursuis la cuisson.","timerMin":5},{"text":"Sers avec des quartiers de citron."}]'::jsonb, 620, 3, true),
  ('rec_penne_thon_tomate', 'Penne au thon, tomate et olives', 'Un plat de placard ultra-rapide, plein de saveurs méditerranéennes.', '🍝', '#F9D5C5', null, 'italienne'::public.cuisine, array['rapide', 'anti-gaspi', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 5, 15, 1, array['plaques']::public.equipment[], '[{"text":"Fais cuire les penne dans l''eau bouillante salée.","timerMin":11},{"text":"Fais revenir l''oignon et l''ail dans l''huile.","timerMin":3},{"text":"Ajoute le coulis et l''origan, laisse mijoter.","timerMin":8},{"text":"Incorpore le thon émietté et les olives."},{"text":"Mélange avec les pâtes égouttées."}]'::jsonb, 530, 1, true),
  ('rec_cabillaud_provencale', 'Cabillaud à la provençale', 'Du poisson rôti sur des tomates cerises, des courgettes et des olives, au parfum d’herbes.', '🍋', '#FDF0C2', null, 'mediterraneenne'::public.cuisine, array['léger', 'de saison']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 20, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C."},{"text":"Mélange les courgettes en dés, les tomates cerises, les olives, l''ail, les herbes et l''huile dans un plat."},{"text":"Enfourne les légumes seuls.","timerMin":10},{"text":"Pose le cabillaud salé sur les légumes et poursuis la cuisson.","timerMin":12},{"text":"Pendant ce temps, fais cuire le riz et sers le tout ensemble.","timerMin":11}]'::jsonb, 410, 3, true),
  ('rec_riz_saute_crevettes', 'Riz sauté aux crevettes', 'Un riz cantonais maison avec œuf brouillé, petits pois et crevettes.', '🍚', '#FBEAC0', null, 'asiatique'::public.cuisine, array['rapide', 'anti-gaspi']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 12, 1, array['plaques']::public.equipment[], '[{"text":"Fais cuire le riz s''il n''est pas déjà cuit, puis étale-le pour qu''il refroidisse.","timerMin":11},{"text":"Fais un œuf brouillé dans un peu d’huile, puis réserve-le.","timerMin":2},{"text":"Saute la carotte en petits dés et les petits pois à feu vif.","timerMin":4},{"text":"Ajoute le riz, les crevettes et la sauce soja, fais sauter en remuant.","timerMin":4},{"text":"Remets l''œuf, parsème d''oignon nouveau et sers."}]'::jsonb, 490, 2, true),
  ('rec_carbonara', 'Spaghetti carbonara', 'La vraie carbonara : jaunes d’œufs, parmesan, lardons croustillants et beaucoup de poivre.', '🥓', '#FCEBC4', null, 'italienne'::public.cuisine, array['rapide', 'comfort', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 12, 2, array['plaques']::public.equipment[], '[{"text":"Fais cuire les spaghetti dans l''eau bouillante salée.","timerMin":10},{"text":"Fais dorer les lardons à sec dans une grande poêle.","timerMin":6},{"text":"Bats les œufs avec le parmesan râpé et beaucoup de poivre."},{"text":"Hors du feu, mélange les pâtes égouttées avec les lardons, puis l’appareil aux œufs et un peu d’eau de cuisson."},{"text":"Remue vivement pour obtenir une sauce crémeuse, sans faire cuire les œufs."}]'::jsonb, 680, 1, true),
  ('rec_quiche_lorraine', 'Quiche lorraine', 'La recette traditionnelle : lardons, œufs et crème sur une pâte brisée dorée.', '🥧', '#FDE6B6', null, 'francaise'::public.cuisine, array['familial', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 15, 35, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 190 °C et garnis un moule de pâte."},{"text":"Fais rissoler les lardons à sec, puis égoutte-les.","timerMin":5},{"text":"Bats les œufs, la crème, le lait, la muscade et le poivre."},{"text":"Répartis les lardons sur la pâte et verse l''appareil."},{"text":"Enfourne jusqu’à ce que la quiche soit bien dorée.","timerMin":35},{"text":"Sers tiède avec une salade verte."}]'::jsonb, 480, 1, true),
  ('rec_tartiflette', 'Tartiflette', 'Pommes de terre, lardons, oignons et reblochon fondant : le plat de montagne par excellence.', '🏔️', '#F6E2B3', null, 'francaise'::public.cuisine, array['comfort', 'de saison', 'week-end']::text[], array['diner']::public.meal_type[], 4, 20, 45, 2, array['four', 'plaques']::public.equipment[], '[{"text":"Fais cuire les pommes de terre dans l''eau salée, puis coupe-les en rondelles.","timerMin":20},{"text":"Préchauffe le four à 200 °C."},{"text":"Fais revenir les oignons émincés et les lardons, puis déglace au vin blanc.","timerMin":8},{"text":"Dans un plat, alterne pommes de terre et lardons-oignons, puis ajoute la crème."},{"text":"Coupe le reblochon en deux dans l’épaisseur et pose-le croûte vers le haut."},{"text":"Enfourne jusqu’à ce que le fromage soit fondu et doré.","timerMin":25}]'::jsonb, 820, 2, true),
  ('rec_galettes_completes', 'Galettes complètes jambon-œuf-fromage', 'La galette bretonne au sarrasin, garnie de jambon, d’un œuf miroir et d’emmental.', '🥞', '#EFD8B4', null, 'francaise'::public.cuisine, array['rapide', 'familial']::text[], array['diner']::public.meal_type[], 4, 10, 15, 3, array['plaques']::public.equipment[], '[{"text":"Mélange la farine de sarrasin, le sel, 1 œuf et l''eau jusqu''à obtenir une pâte lisse (idéalement, laisse-la reposer)."},{"text":"Beurre une grande poêle chaude et verse une louche de pâte en l’étalant finement.","timerMin":2},{"text":"Garnis d’emmental, d’une tranche de jambon et casse un œuf au centre.","timerMin":2},{"text":"Laisse cuire jusqu’à ce que le blanc soit pris, puis replie les bords en carré.","timerMin":2},{"text":"Recommence pour les autres galettes et sers aussitôt."}]'::jsonb, 520, 1, true),
  ('rec_saucisses_lentilles', 'Saucisses de Toulouse aux lentilles', 'Un plat mijoté rustique où les lentilles s’imprègnent du goût des saucisses.', '🌭', '#E8D5BF', null, 'francaise'::public.cuisine, array['comfort', 'de saison', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 35, 1, array['plaques']::public.equipment[], '[{"text":"Fais dorer les saucisses dans une cocotte, puis réserve-les.","timerMin":6},{"text":"Fais revenir l''oignon et les carottes en rondelles dans la graisse des saucisses.","timerMin":4},{"text":"Ajoute les lentilles, l''eau, le cube de bouillon, le laurier et le thym.","timerMin":1},{"text":"Remets les saucisses et laisse mijoter à couvert.","timerMin":25},{"text":"Retire le laurier, rectifie l’assaisonnement et sers bien chaud."}]'::jsonb, 640, 2, true),
  ('rec_filet_mignon_moutarde', 'Filet mignon sauce moutarde', 'Un filet mignon tendre nappé d’une sauce crémeuse à la moutarde, avec des haricots verts.', '🍖', '#F4E3C3', null, 'francaise'::public.cuisine, array['week-end', 'comfort']::text[], array['diner']::public.meal_type[], 4, 10, 25, 2, array['plaques']::public.equipment[], '[{"text":"Coupe le filet mignon en médaillons épais."},{"text":"Fais-les dorer dans l''huile, 4 minutes par face, puis réserve-les au chaud.","timerMin":8},{"text":"Fais suer l''échalote hachée, ajoute la crème et la moutarde, laisse réduire.","timerMin":5},{"text":"Remets la viande dans la sauce pour finir la cuisson.","timerMin":5},{"text":"Pendant ce temps, fais cuire les haricots verts à l''eau salée puis poêle-les au beurre.","timerMin":10},{"text":"Sers les médaillons nappés de sauce avec les haricots."}]'::jsonb, 480, 3, true),
  ('rec_endives_jambon', 'Endives au jambon gratinées', 'Des endives fondantes roulées dans du jambon, sous une béchamel gratinée.', '🥬', '#F2EFC9', null, 'francaise'::public.cuisine, array['de saison', 'comfort', 'familial']::text[], array['diner']::public.meal_type[], 4, 15, 40, 2, array['four', 'plaques']::public.equipment[], '[{"text":"Fais cuire les endives à la poêle à couvert avec une noisette de beurre, puis égoutte-les bien.","timerMin":15},{"text":"Préchauffe le four à 200 °C."},{"text":"Prépare une béchamel avec le reste du beurre, la farine et le lait.","timerMin":6},{"text":"Assaisonne de muscade et de sel."},{"text":"Roule chaque endive dans une tranche de jambon et range-les dans un plat."},{"text":"Nappe de béchamel, parsème d''emmental et fais gratiner.","timerMin":20}]'::jsonb, 450, 2, true),
  ('rec_croque_monsieur', 'Croque-monsieur et salade', 'Le croque doré au beurre, jambon et emmental fondant, avec une salade verte.', '🥪', '#FBE9C6', null, 'francaise'::public.cuisine, array['rapide', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 10, 1, array['four']::public.equipment[], '[{"text":"Préchauffe le four à 220 °C."},{"text":"Beurre les tranches de pain sur une face."},{"text":"Monte les croques : pain, emmental, jambon, emmental, pain, face beurrée à l''extérieur."},{"text":"Parsème le dessus d''emmental et enfourne.","timerMin":10},{"text":"Sers avec la salade assaisonnée."}]'::jsonb, 520, 1, true),
  ('rec_poulet_basquaise', 'Poulet basquaise', 'Des cuisses de poulet mijotées avec des poivrons, des tomates et une pointe de piment.', '🫑', '#F9D3BE', null, 'francaise'::public.cuisine, array['familial', 'batch', 'de saison']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 45, 2, array['plaques']::public.equipment[], '[{"text":"Fais dorer les cuisses de poulet sur toutes les faces dans l''huile d''olive, puis réserve-les.","timerMin":10},{"text":"Fais revenir les oignons et les poivrons en lanières dans la même cocotte.","timerMin":8},{"text":"Ajoute l''ail, le paprika, le piment et les tomates.","timerMin":2},{"text":"Remets le poulet, couvre et laisse mijoter.","timerMin":35},{"text":"Fais cuire le riz pendant les dernières minutes.","timerMin":11},{"text":"Sers le poulet nappé de sauce avec le riz."}]'::jsonb, 560, 2, true),
  ('rec_poulet_roti_pdt', 'Cuisses de poulet rôties et pommes de terre', 'Le rôti du dimanche version simple : poulet doré, pommes de terre fondantes, ail et thym.', '🍗', '#FBE2B9', null, 'francaise'::public.cuisine, array['familial', 'week-end', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 50, 1, array['four']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C."},{"text":"Coupe les pommes de terre en quartiers et mets-les dans un grand plat avec les gousses d’ail en chemise."},{"text":"Pose les cuisses de poulet dessus, arrose d''huile et de jus de citron, parsème de thym, sel et poivre."},{"text":"Enfourne en arrosant le poulet de son jus à mi-cuisson.","timerMin":50},{"text":"Laisse reposer 5 minutes avant de servir."}]'::jsonb, 610, 2, true),
  ('rec_curry_poulet', 'Curry de poulet au lait de coco', 'Des morceaux de poulet tendres dans une sauce coco-tomate parfumée.', '🍛', '#FCDDB0', null, 'indienne'::public.cuisine, array['familial', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 25, 1, array['plaques']::public.equipment[], '[{"text":"Coupe le poulet en morceaux."},{"text":"Fais revenir l''oignon, l''ail et le gingembre dans l''huile, ajoute le curry.","timerMin":4},{"text":"Ajoute le poulet et fais-le dorer.","timerMin":5},{"text":"Verse les tomates et le lait de coco, laisse mijoter.","timerMin":15},{"text":"Fais cuire le riz.","timerMin":11},{"text":"Sers parsemé de coriandre."}]'::jsonb, 590, 2, true),
  ('rec_tajine_poulet_citron', 'Tajine de poulet aux citrons et olives', 'Un poulet fondant au gingembre et au curcuma, relevé de citron et d’olives.', '🍋', '#F9EDB0', null, 'orientale'::public.cuisine, array['familial', 'week-end']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 50, 2, array['plaques']::public.equipment[], '[{"text":"Fais dorer le poulet dans l''huile d''olive, puis réserve-le.","timerMin":8},{"text":"Fais fondre les oignons émincés avec l''ail, le gingembre, le curcuma et le cumin.","timerMin":6},{"text":"Remets le poulet, ajoute l''eau, un citron en quartiers et la moitié de la coriandre.","timerMin":1},{"text":"Couvre et laisse mijoter à feu doux.","timerMin":35},{"text":"Ajoute les olives et le jus du second citron, poursuis la cuisson à découvert.","timerMin":10},{"text":"Parsème du reste de coriandre et sers."}]'::jsonb, 520, 2, true),
  ('rec_couscous_poulet_merguez', 'Couscous poulet-merguez', 'Le couscous des grandes tablées : poulet, merguez, légumes et pois chiches.', '🍲', '#F6D3A8', null, 'orientale'::public.cuisine, array['convivial', 'week-end', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 25, 50, 3, array['plaques']::public.equipment[], '[{"text":"Fais dorer les cuisses de poulet dans l''huile avec les oignons et le ras el hanout.","timerMin":8},{"text":"Ajoute les tomates, le concentré, les carottes en tronçons et l''eau. Laisse mijoter.","timerMin":25},{"text":"Ajoute les courgettes et les pois chiches, poursuis la cuisson.","timerMin":15},{"text":"Fais griller les merguez à la poêle.","timerMin":10},{"text":"Prépare la semoule : couvre-la du même volume d''eau bouillante salée et d''un filet d''huile, puis égrène-la.","timerMin":5},{"text":"Sers la semoule avec la viande, les légumes et le bouillon à part."}]'::jsonb, 780, 2, true),
  ('rec_chili_con_carne', 'Chili con carne', 'Le chili familial : bœuf haché, haricots rouges et épices, mijotés pour plus de goût.', '🌶️', '#F4C4B4', null, 'mexicaine'::public.cuisine, array['batch', 'familial', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 35, 1, array['plaques']::public.equipment[], '[{"text":"Fais revenir l''oignon et le poivron hachés dans l''huile.","timerMin":5},{"text":"Ajoute la viande et fais-la dorer en l’émiettant.","timerMin":5},{"text":"Ajoute l''ail, le cumin et le piment, puis les tomates.","timerMin":1},{"text":"Laisse mijoter à couvert, puis ajoute les haricots rouges égouttés.","timerMin":25},{"text":"Fais cuire le riz.","timerMin":11},{"text":"Sers le chili sur le riz."}]'::jsonb, 620, 2, true),
  ('rec_spaghetti_bolognaise', 'Spaghetti bolognaise', 'Une sauce bolognaise mijotée aux légumes, comme en Émilie-Romagne.', '🍝', '#F6CDBE', null, 'italienne'::public.cuisine, array['familial', 'batch', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 40, 1, array['plaques']::public.equipment[], '[{"text":"Hache finement l''oignon, la carotte et le céleri."},{"text":"Fais-les suer dans l''huile d''olive.","timerMin":6},{"text":"Ajoute la viande et laisse-la colorer en l’émiettant.","timerMin":5},{"text":"Ajoute l''ail, le coulis, le concentré et les herbes. Laisse mijoter à couvert.","timerMin":30},{"text":"Fais cuire les spaghetti dans l''eau bouillante salée.","timerMin":10},{"text":"Sers la sauce sur les pâtes, avec du parmesan râpé si tu veux."}]'::jsonb, 650, 2, true),
  ('rec_boeuf_bourguignon', 'Bœuf bourguignon', 'Le grand mijoté français : bœuf fondant au vin rouge, carottes et champignons.', '🍷', '#E9CFCB', null, 'francaise'::public.cuisine, array['week-end', 'batch', 'comfort', 'de saison']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 25, 150, 3, array['plaques']::public.equipment[], '[{"text":"Coupe le bœuf en gros cubes et fais-les dorer par petites quantités dans l’huile.","timerMin":10},{"text":"Fais revenir les oignons et l''ail, remets la viande et saupoudre de farine.","timerMin":5},{"text":"Verse le vin rouge, ajoute le cube de bouillon, le laurier, le thym et les carottes en rondelles."},{"text":"Couvre et laisse mijoter à feu très doux.","timerMin":120},{"text":"Ajoute les champignons émincés et poursuis la cuisson.","timerMin":30},{"text":"Fais cuire les pommes de terre à l''eau et sers-les avec le bourguignon.","timerMin":20}]'::jsonb, 640, 3, true),
  ('rec_hachis_parmentier', 'Hachis parmentier', 'Une purée maison dorée sur un hachis de bœuf aux oignons, le réconfort absolu.', '🥔', '#F5E3BE', null, 'francaise'::public.cuisine, array['familial', 'comfort', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 40, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Fais cuire les pommes de terre épluchées à l''eau salée.","timerMin":20},{"text":"Fais revenir les oignons dans l''huile, ajoute la viande et fais-la dorer.","timerMin":8},{"text":"Écrase les pommes de terre avec le lait chaud, le beurre, la muscade et le sel."},{"text":"Préchauffe le four à 200 °C."},{"text":"Étale la viande dans un plat, recouvre de purée et parsème d''emmental."},{"text":"Fais gratiner.","timerMin":20}]'::jsonb, 640, 2, true),
  ('rec_burgers_maison', 'Burgers maison et potatoes', 'Des burgers juteux au cheddar et des potatoes croustillantes au paprika.', '🍔', '#FBDDB3', null, 'americaine'::public.cuisine, array['familial', 'week-end']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 30, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 210 °C."},{"text":"Coupe les pommes de terre en quartiers, mélange-les avec l''huile, le paprika et le sel, puis enfourne.","timerMin":30},{"text":"Façonne 4 steaks avec la viande et sale-les."},{"text":"Fais-les cuire à la poêle bien chaude et pose une tranche de cheddar en fin de cuisson.","timerMin":6},{"text":"Toaste les pains, puis monte les burgers avec ketchup, salade, tomate et oignon rouge."}]'::jsonb, 820, 2, true),
  ('rec_boulettes_kefta', 'Boulettes kefta à la sauce tomate', 'Des boulettes de bœuf au cumin et aux herbes, mijotées dans une sauce tomate épicée.', '🧆', '#F3C7B3', null, 'orientale'::public.cuisine, array['familial', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 25, 2, array['plaques']::public.equipment[], '[{"text":"Mélange la viande avec l''oignon râpé, les herbes hachées, la moitié des épices, l''œuf, la chapelure et le sel."},{"text":"Forme une vingtaine de petites boulettes."},{"text":"Fais-les dorer dans l''huile, puis réserve-les.","timerMin":6},{"text":"Verse les tomates et le reste des épices, remets les boulettes et laisse mijoter.","timerMin":15},{"text":"Prépare la semoule avec le même volume d''eau bouillante salée.","timerMin":5},{"text":"Sers les boulettes et la sauce sur la semoule."}]'::jsonb, 640, 2, true),
  ('rec_dinde_creme_champignons', 'Escalopes de dinde à la crème et aux champignons', 'Des escalopes tendres dans une sauce crémeuse aux champignons, avec du riz.', '🍄', '#EFE3D0', null, 'francaise'::public.cuisine, array['rapide', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 15, 1, array['plaques']::public.equipment[], '[{"text":"Lance la cuisson du riz.","timerMin":11},{"text":"Fais dorer les escalopes dans l''huile, 3 minutes par face, puis réserve-les.","timerMin":6},{"text":"Fais revenir l''échalote et les champignons émincés.","timerMin":5},{"text":"Ajoute la crème, sale, poivre et remets les escalopes pour les réchauffer.","timerMin":3},{"text":"Sers avec le riz."}]'::jsonb, 520, 2, true),
  ('rec_poulet_teriyaki', 'Poulet teriyaki, riz et brocoli', 'Du poulet laqué soja-miel-gingembre, du riz et du brocoli croquant.', '🍱', '#F8DFC0', null, 'asiatique'::public.cuisine, array['rapide', 'familial']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 10, 15, 1, array['plaques']::public.equipment[], '[{"text":"Lance la cuisson du riz.","timerMin":11},{"text":"Fais cuire les bouquets de brocoli à la vapeur ou à l’eau.","timerMin":6},{"text":"Coupe le poulet en lanières et fais-le dorer dans l''huile.","timerMin":6},{"text":"Ajoute la sauce soja, le miel, l''ail et le gingembre râpés, laisse caraméliser.","timerMin":3},{"text":"Sers sur le riz avec le brocoli et parsème de sésame."}]'::jsonb, 560, 2, true),
  ('rec_fajitas_poulet', 'Fajitas de poulet aux poivrons', 'Du poulet épicé et des poivrons saisis, à rouler dans des tortillas avec de l’avocat.', '🌯', '#FBD9B9', null, 'mexicaine'::public.cuisine, array['rapide', 'familial', 'street food']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 10, 1, array['plaques']::public.equipment[], '[{"text":"Coupe le poulet, les poivrons et l’oignon en lanières."},{"text":"Mélange le poulet avec le paprika, le cumin et le jus du citron vert."},{"text":"Saisis le poulet dans l''huile bien chaude, puis ajoute les légumes.","timerMin":8},{"text":"Réchauffe les tortillas.","timerMin":2},{"text":"Garnis-les de poulet, de légumes et d’avocat écrasé, puis roule-les."}]'::jsonb, 590, 2, true),
  ('rec_moussaka', 'Moussaka', 'Aubergines fondantes, bœuf à la cannelle et béchamel dorée : le gratin grec.', '🍆', '#E6D0E4', null, 'mediterraneenne'::public.cuisine, array['week-end', 'batch', 'de saison']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 30, 60, 3, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C."},{"text":"Coupe les aubergines en tranches, badigeonne-les d''huile et fais-les rôtir sur une plaque.","timerMin":20},{"text":"Fais revenir l''oignon et l''ail, ajoute la viande, la cannelle et les tomates. Laisse mijoter.","timerMin":15},{"text":"Prépare une béchamel avec le beurre, la farine et le lait, puis ajoute le parmesan.","timerMin":6},{"text":"Alterne aubergines et sauce à la viande dans un plat, puis nappe de béchamel."},{"text":"Fais gratiner, puis laisse reposer 10 minutes avant de couper.","timerMin":35}]'::jsonb, 590, 2, true),
  ('rec_wok_boeuf_nouilles', 'Wok de bœuf aux nouilles et légumes', 'Des lamelles de bœuf saisies, des légumes croquants et des nouilles sautées à la sauce soja.', '🥢', '#E9DCC4', null, 'asiatique'::public.cuisine, array['rapide']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 10, 2, array['plaques']::public.equipment[], '[{"text":"Fais cuire les nouilles dans l''eau bouillante, puis égoutte-les.","timerMin":4},{"text":"Coupe les légumes en fines lanières."},{"text":"Saisis le bœuf à feu très vif dans l''huile, puis réserve-le.","timerMin":2},{"text":"Fais sauter les légumes avec l''ail et le gingembre.","timerMin":4},{"text":"Ajoute les nouilles, le bœuf et la sauce soja, mélange sur le feu.","timerMin":1},{"text":"Sers aussitôt."}]'::jsonb, 580, 3, true),
  ('rec_tajine_agneau', 'Tajine d''agneau aux carottes et pois chiches', 'Un agneau confit aux épices douces, avec des carottes fondantes et des pois chiches.', '🫕', '#F1CFA9', null, 'orientale'::public.cuisine, array['week-end', 'comfort', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 90, 2, array['plaques']::public.equipment[], '[{"text":"Coupe l''agneau en morceaux et fais-le dorer dans l''huile.","timerMin":8},{"text":"Ajoute les oignons, l''ail, le ras el hanout et la cannelle.","timerMin":3},{"text":"Verse l''eau, ajoute le miel, couvre et laisse mijoter.","timerMin":60},{"text":"Ajoute les carottes en tronçons et les pois chiches, poursuis la cuisson.","timerMin":25},{"text":"Prépare la semoule avec le même volume d''eau bouillante salée.","timerMin":5},{"text":"Parsème de coriandre et sers avec la semoule."}]'::jsonb, 680, 3, true),
  ('rec_salade_cesar_poulet', 'Salade César au poulet', 'Poulet doré, croûtons, parmesan et une sauce César crémeuse au citron.', '🥙', '#E7F1D2', null, 'americaine'::public.cuisine, array['rapide', 'léger']::text[], array['dejeuner']::public.meal_type[], 4, 15, 10, 1, array['plaques']::public.equipment[], '[{"text":"Coupe le pain de mie en cubes et fais-les dorer dans 1 cuillère d''huile.","timerMin":3},{"text":"Fais cuire le poulet dans le reste d''huile, puis tranche-le.","timerMin":7},{"text":"Mélange la mayonnaise avec le jus de citron, l''ail râpé et la moitié du parmesan râpé."},{"text":"Mélange la salade avec la sauce, puis ajoute le poulet, les croûtons et le reste de parmesan en copeaux."}]'::jsonb, 520, 2, true),
  ('rec_pot_au_feu', 'Pot-au-feu', 'Le bœuf et ses légumes cuits longuement dans un bouillon parfumé, à servir avec de la moutarde.', '🍲', '#EADBC2', null, 'francaise'::public.cuisine, array['week-end', 'batch', 'de saison', 'comfort']::text[], array['dejeuner', 'diner']::public.meal_type[], 6, 25, 180, 2, array['plaques']::public.equipment[], '[{"text":"Mets la viande dans un grand faitout couvert d''eau froide et porte à frémissement en écumant.","timerMin":15},{"text":"Ajoute l''oignon, le laurier, le thym et le sel, puis laisse frémir à couvert.","timerMin":120},{"text":"Ajoute les carottes, les poireaux et le céleri en tronçons.","timerMin":30},{"text":"Ajoute les pommes de terre et poursuis la cuisson.","timerMin":30},{"text":"Sers la viande et les légumes avec un peu de bouillon et de la moutarde."}]'::jsonb, 520, 2, true),
  ('rec_pad_thai_poulet', 'Pad thaï au poulet', 'Des nouilles de riz sautées au poulet et à l’œuf, avec cacahuètes et citron vert.', '🥜', '#F8E2BE', null, 'asiatique'::public.cuisine, array['rapide', 'street food']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 10, 2, array['plaques']::public.equipment[], '[{"text":"Fais tremper les nouilles de riz dans l''eau chaude, puis égoutte-les.","timerMin":5},{"text":"Mélange la sauce soja, le sucre et le jus d’un citron vert."},{"text":"Fais sauter le poulet émincé et l''ail dans l''huile.","timerMin":5},{"text":"Pousse le poulet sur le côté, brouille les œufs, puis ajoute la carotte râpée, les nouilles et la sauce.","timerMin":3},{"text":"Sers avec les cacahuètes concassées, l''oignon nouveau et des quartiers de citron vert."}]'::jsonb, 610, 2, true),
  ('rec_poulet_citron_quinoa', 'Poulet grillé, quinoa et légumes rôtis', 'Un poulet mariné au citron et aux herbes, avec du quinoa et des légumes du four.', '🥗', '#E5F0CF', null, 'mediterraneenne'::public.cuisine, array['léger', 'batch']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 15, 25, 1, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 210 °C."},{"text":"Coupe les légumes en morceaux, arrose-les de 2 cuillères d''huile, sale et enfourne.","timerMin":25},{"text":"Fais mariner le poulet avec le jus de citron, les herbes et le reste d''huile."},{"text":"Fais cuire le quinoa.","timerMin":12},{"text":"Fais griller le poulet à la poêle.","timerMin":10},{"text":"Sers le poulet tranché sur le quinoa avec les légumes rôtis."}]'::jsonb, 540, 2, true),
  ('rec_gratin_courgettes_boeuf', 'Courgettes farcies au bœuf', 'Des courgettes gourmandes farcies de bœuf haché aux herbes, gratinées au four.', '🥒', '#DCEBC7', null, 'francaise'::public.cuisine, array['de saison', 'familial', 'anti-gaspi']::text[], array['dejeuner', 'diner']::public.meal_type[], 4, 20, 35, 2, array['four', 'plaques']::public.equipment[], '[{"text":"Préchauffe le four à 200 °C."},{"text":"Coupe les courgettes en deux dans la longueur et évide-les à la cuillère."},{"text":"Fais revenir l''oignon, l''ail, la chair de courgette hachée et la viande dans l''huile.","timerMin":8},{"text":"Ajoute les tomates et les herbes, sale et laisse réduire.","timerMin":5},{"text":"Farcis les courgettes, parsème d''emmental et enfourne.","timerMin":30},{"text":"Sers avec du riz.","timerMin":11}]'::jsonb, 450, 2, true)
